func:
// Persistent virtual-estimator state (context survives across ticks; msg does not).
// Instead of independent random draws each second, we random-walk a single
// "load" scalar (0-1, how hard the pump is working) with mean reversion, plus
// occasional FAULT/STOPPED episodes. All 6 metrics are derived FROM load
// (+ a fault-severity ramp), so they move together the way real pump
// telemetry does, instead of jumping to unrelated random numbers every tick.
//
// FAULT episodes now carry a faultType so each failure mode has its own
// metric signature instead of one generic ramp applied evenly to all 6
// metrics -- this is what lets the dashboard/model later tell "why" a fault
// is happening, not just "that" it is happening.
//   THERMAL       -- motor overheating: motorTemp spikes hard, rpm sags as
//                    the motor struggles, everything else only mildly affected.
//   CAVITATION    -- suction starves the pump: suctionPressure and flowRate
//                    both collapse, dischargePressure follows them down.
//   BEARING       -- mechanical wear: vibration spikes hard, rpm becomes
//                    unstable (sags), motorTemp rises moderately from friction.
//   IMPELLER_WEAR -- erosion/damage/partial clog on the impeller: flow and
//                    discharge pressure drop for the SAME rpm (efficiency
//                    loss, not a speed change); suctionPressure ticks UP
//                    slightly (flow backs up), opposite direction from
//                    CAVITATION's suction collapse -- that's what makes the
//                    two distinguishable from each other.
//   SEAL_LEAK     -- mechanical seal wear/failure: mostly a pressure story,
//                    discharge pressure drops from internal leakage with
//                    almost no vibration/thermal signal -- deliberately the
//                    'quiet' fault, since none of the others produce a
//                    pressure-only signature.
//   MISALIGNMENT  -- shaft/coupling misalignment: vibration-dominant like
//                    BEARING but a different ratio (smaller flow/pressure
//                    hit, temp rises from mechanical strain not friction).
//                    NOTE: with only these 6 scalar metrics (no vibration
//                    frequency spectrum, no motor current), this is genuinely
//                    hard to separate from BEARING -- don't expect Tier 2 to
//                    cleanly distinguish the two without richer
//                    instrumentation eventually.
//   DRY_RUN       -- pump loses prime / runs with no or partial fluid: the
//                    most severe and fastest-onset fault -- flow/pressure
//                    collapse almost completely, rpm RISES (no fluid load
//                    to resist the motor), temp climbs fast (no fluid to
//                    cool bearings/seals). Distinct from CAVITATION by rpm
//                    direction and speed of onset.
// Each profile is a per-metric delta APPLIED AT fault=1 (full severity);
// it scales linearly with faultSeverity like the old single fault term did.

function clamp(v, min, max) { return Math.max(min, Math.min(max, v)); }
function jitter(scale) { return (Math.random() - 0.5) * 2 * scale; }
function randInt(min, max) { return Math.floor(Math.random() * (max - min + 1)) + min; }
function step(current, target, speed, noise) { return current + speed * (target - current) + jitter(noise); }

const FAULT_PROFILES = {
    THERMAL:      { flowRate: -20,  rpm: -150, vibration: 2,   suctionPressure: 0,    dischargePressure: -1,  motorTemp: 45 },
    CAVITATION:   { flowRate: -110, rpm: 50,   vibration: 5,   suctionPressure: -1.2, dischargePressure: -6,  motorTemp: 8  },
    BEARING:      { flowRate: -10,  rpm: -300, vibration: 9,   suctionPressure: 0,    dischargePressure: 0,   motorTemp: 15 },
    IMPELLER_WEAR:{ flowRate: -60,  rpm: 0,    vibration: 4,   suctionPressure: 0.3,  dischargePressure: -3,  motorTemp: 10 },
    SEAL_LEAK:    { flowRate: -15,  rpm: 0,    vibration: 0.5, suctionPressure: 0,    dischargePressure: -4,  motorTemp: 0  },
    MISALIGNMENT: { flowRate: -5,   rpm: -50,  vibration: 6,   suctionPressure: 0,    dischargePressure: -1,  motorTemp: 12 },
    DRY_RUN:      { flowRate: -180, rpm: 100,  vibration: 7,   suctionPressure: -2.5, dischargePressure: -15, motorTemp: 25 }
};
const FAULT_TYPES = Object.keys(FAULT_PROFILES);

let state = context.get('state');
if (!state) {
    state = { load: 0.5, regime: 'RUNNING', regimeTicksLeft: 0, regimeTotalTicks: 0, faultSeverity: 0, faultType: null };
}

// Regime transitions: mostly RUNNING, with rare FAULT / STOPPED episodes.
if (state.regimeTicksLeft > 0) {
    state.regimeTicksLeft--;
    if (state.regimeTicksLeft === 0) {
        state.regime = 'RUNNING';
        state.faultSeverity = 0;
        state.faultType = null;
    }
} else if (state.regime === 'RUNNING') {
    if (Math.random() < 0.003) {
        state.regime = 'FAULT';
        state.faultType = FAULT_TYPES[randInt(0, FAULT_TYPES.length - 1)];
        state.regimeTotalTicks = randInt(15, 40);
        state.regimeTicksLeft = state.regimeTotalTicks;
    } else if (Math.random() < 0.002) {
        state.regime = 'STOPPED';
        state.regimeTotalTicks = randInt(20, 60);
        state.regimeTicksLeft = state.regimeTotalTicks;
    }
}

// Fault severity ramps 0 -> ~1 across the episode, then resets on recovery.
if (state.regime === 'FAULT') {
    state.faultSeverity = 1 - (state.regimeTicksLeft / state.regimeTotalTicks);
}

// "load" = how hard the pump is working (0-1). Random-walks with mean
// reversion toward a regime-specific target, so it drifts smoothly instead
// of teleporting -- this is what gives every metric real momentum/trend.
const loadTarget = state.regime === 'STOPPED' ? 0.02 : 0.5;
const loadSpeed  = state.regime === 'STOPPED' ? 0.35 : 0.06;
const loadNoise  = state.regime === 'STOPPED' ? 0.02 : 0.05;
state.load = clamp(step(state.load, loadTarget, loadSpeed, loadNoise), 0.02, 1);

// Noise gets louder as fault severity rises (heteroscedastic measurement noise).
const noiseScale = 1 + state.faultSeverity * 2;
const load = state.load;
const fault = state.faultSeverity;
const profile = state.faultType ? FAULT_PROFILES[state.faultType] : null;
function delta(metric) { return profile ? fault * profile[metric] : 0; }

function round1(v) { return Math.round(v * 10) / 10; }

// NOTE: state.faultType (which FAULT_PROFILES entry is driving this
// episode's metric deltas) is intentionally NOT included below. Real
// sensors report readings and operational status, never a diagnosis --
// faultType is a HITL reviewer's conclusion (fault_events.faultType, set
// on review/confirm), or later an auto-classification once a reviewed
// signature repeats. Leaking the ground-truth label into the live stream
// would make Tier 1/Tier 2 trivial and defeat the point of building them.
msg.payload = {
    flowRate:          round1(clamp(50   + load * 250 + delta('flowRate')          + jitter(6    * noiseScale), 50,   300)),
    rpm:               round1(clamp(1000 + load * 2600 + delta('rpm')              + jitter(30   * noiseScale), 1000, 3600)),
    vibration:         round1(clamp(0.5  + load * 4   + delta('vibration')         + jitter(0.4  * noiseScale), 0.5,  12)),
    suctionPressure:   round1(clamp(3    - load * 2.5 + delta('suctionPressure')   + jitter(0.08 * noiseScale), 0.5,  3)),
    dischargePressure: round1(clamp(2    + load * 10  + delta('dischargePressure') + jitter(0.3  * noiseScale), 2,    12)),
    motorTemp:         round1(clamp(20   + load * 40  + delta('motorTemp')         + jitter(1.5  * noiseScale), 20,   90)),
    status:            state.regime,
    timestamp:         new Date().toISOString()
};

context.set('state', state);

// Tell the backend the body is JSON so Express parses it correctly.
msg.headers = { "Content-Type": "application/json" };

return msg;

// The message a Catch node receives is the ORIGINAL message that entered
// the failing node — msg.payload is still the reading object built by
// gen_reading, not a response body, since the request never succeeded.
const MAX_RETRIES = 3;
msg.retryCount = (msg.retryCount || 0) + 1;

if (msg.retryCount > MAX_RETRIES) {
    node.warn(`POST /api/data failed after ${MAX_RETRIES} retries -- dropping reading for ${msg.payload && msg.payload.timestamp}`);
    return null; // give up; this tick's reading is genuinely lost, same as before the retry queue existed
}

node.warn(`POST /api/data failed (attempt ${msg.retryCount}/${MAX_RETRIES}) -- retrying in 1s for ${msg.payload && msg.payload.timestamp}`);
msg.headers = { "Content-Type": "application/json" };
return msg;
